def diagnostic_fixture_from_framework(source: str) -> str:
    """Reverse only the eight exact independently reviewable fixture fragments."""
    if type(source) is not str or hashlib.sha256(source.encode()).hexdigest() != QUALIFIED_FRAMEWORK_FIXTURE_SHA256:
        raise ValueError("Exact qualified real-framework fixture is required")
    restored = source
    for before, after in reversed(FRAMEWORK_DELTAS):
        if restored.count(after) != 1:
            raise ValueError("Each exact real-framework delta must occur once")
        restored = restored.replace(after, before, 1)
    if hashlib.sha256(restored.encode()).hexdigest() != DIAGNOSTIC_FIXTURE_SHA256:
        raise ValueError("Framework inverse must preserve the entire diagnostic fixture")
    return restored
